-- [JLAS-W0108] Approved Smart Test N3 corrections
-- N3-020 distractors are already corrected in questionbank.sql for fresh installs.
-- This guarded repair converges older rows only when no learner has seen them.
START TRANSACTION;

UPDATE assessment_question q
SET q.option_1 = '教室',
    q.option_2 = '校庭',
    q.option_3 = '階段'
WHERE q.skill = 'KANJI'
  AND q.jlpt_level = 'N3'
  AND JSON_UNQUOTE(JSON_EXTRACT(q.context_json, '$.seed_key')) = 'KANJI-DIVERSE-N3-020'
  AND q.answer_text = '廊下'
  AND q.correct_option = 4
  AND q.option_1 = '取る'
  AND q.option_2 = '引く'
  AND q.option_3 = '押す'
  AND q.option_4 = '廊下'
  AND NOT EXISTS (SELECT 1 FROM smart_test_session_question sq WHERE sq.question_id = q.id)
  AND NOT EXISTS (SELECT 1 FROM assessment_answer a WHERE a.question_id = q.id);

SELECT ROW_COUNT() AS repaired_rows;
COMMIT;

SELECT q.id, q.option_1, q.option_2, q.option_3, q.option_4,
       q.correct_option, q.answer_text
FROM assessment_question q
WHERE JSON_UNQUOTE(JSON_EXTRACT(q.context_json, '$.seed_key')) = 'KANJI-DIVERSE-N3-020';

-- Owner-approved N3 Kanji JLPT retag (2026-10-13); idempotent for existing databases.
SET NAMES utf8mb4;
START TRANSACTION;

UPDATE assessment_question q
SET q.context_json = JSON_ARRAY_APPEND(q.context_json, '$.additional_tags', 'JLPT')
WHERE q.skill = 'KANJI'
  AND q.jlpt_level = 'N3'
  AND q.is_active = 1
  AND JSON_UNQUOTE(JSON_EXTRACT(q.context_json, '$.seed_batch')) = 'KANJI_N5_N1_DIVERSE_V3'
  AND JSON_UNQUOTE(JSON_EXTRACT(q.context_json, '$.seed_key')) IN (
      'KANJI-DIVERSE-N3-001', 'KANJI-DIVERSE-N3-004',
      'KANJI-DIVERSE-N3-006', 'KANJI-DIVERSE-N3-007',
      'KANJI-DIVERSE-N3-010', 'KANJI-DIVERSE-N3-013',
      'KANJI-DIVERSE-N3-022', 'KANJI-DIVERSE-N3-023',
      'KANJI-DIVERSE-N3-024', 'KANJI-DIVERSE-N3-025',
      'KANJI-DIVERSE-N3-026', 'KANJI-DIVERSE-N3-027',
      'KANJI-DIVERSE-N3-028', 'KANJI-DIVERSE-N3-030',
      'KANJI-DIVERSE-N3-031', 'KANJI-DIVERSE-N3-032',
      'KANJI-DIVERSE-N3-034', 'KANJI-DIVERSE-N3-037',
      'KANJI-DIVERSE-N3-038', 'KANJI-DIVERSE-N3-041')
  AND JSON_TYPE(JSON_EXTRACT(q.context_json, '$.additional_tags')) = 'ARRAY'
  AND NOT JSON_CONTAINS(JSON_EXTRACT(q.context_json, '$.additional_tags'), JSON_QUOTE('JLPT'))
  AND q.answer_text = ELT(q.correct_option, q.option_1, q.option_2, q.option_3, q.option_4)
  AND q.option_1 <> q.option_2 AND q.option_1 <> q.option_3 AND q.option_1 <> q.option_4
  AND q.option_2 <> q.option_3 AND q.option_2 <> q.option_4 AND q.option_3 <> q.option_4;

SELECT ROW_COUNT() AS newly_retagged_rows;
COMMIT;

SELECT COUNT(*) AS candidate_rows_with_jlpt_tag,
       COUNT(DISTINCT JSON_UNQUOTE(JSON_EXTRACT(q.context_json, '$.lexeme'))) AS distinct_lexemes
FROM assessment_question q
WHERE JSON_UNQUOTE(JSON_EXTRACT(q.context_json, '$.seed_key')) IN (
      'KANJI-DIVERSE-N3-001', 'KANJI-DIVERSE-N3-004',
      'KANJI-DIVERSE-N3-006', 'KANJI-DIVERSE-N3-007',
      'KANJI-DIVERSE-N3-010', 'KANJI-DIVERSE-N3-013',
      'KANJI-DIVERSE-N3-022', 'KANJI-DIVERSE-N3-023',
      'KANJI-DIVERSE-N3-024', 'KANJI-DIVERSE-N3-025',
      'KANJI-DIVERSE-N3-026', 'KANJI-DIVERSE-N3-027',
      'KANJI-DIVERSE-N3-028', 'KANJI-DIVERSE-N3-030',
      'KANJI-DIVERSE-N3-031', 'KANJI-DIVERSE-N3-032',
      'KANJI-DIVERSE-N3-034', 'KANJI-DIVERSE-N3-037',
      'KANJI-DIVERSE-N3-038', 'KANJI-DIVERSE-N3-041')
  AND JSON_CONTAINS(JSON_EXTRACT(q.context_json, '$.additional_tags'), JSON_QUOTE('JLPT'));

-- BEGIN generated communication-goal lessons (learning-content.json)
-- SOURCE SHA256 communication_path_release=4b0da62552a9c2cace724b0683b78a262e1a0a4ddbccc3f8e2b484d0327a93d7 goal_source_snapshots=16b3246214903b807ee5b579a0db7cbc7773aecb509a19ef2ed99749d1ce1cba
-- Generated. Edit the canonical JSON section and run this generator; do not hand-edit this block.
-- Communication lessons have no scored quiz or JLPT grading. TTS is an explicit browser-speech sentinel.
-- Attribution: JMdict / EDRDG, CC BY-SA 4.0 https://www.edrdg.org/edrdg/licence.html
-- Fails closed: any validator SIGNAL aborts before COMMIT, so the whole block rolls back.
SET NAMES utf8mb4;
DELIMITER //
DROP PROCEDURE IF EXISTS jlas_validate_comm_path_v1//
CREATE PROCEDURE jlas_validate_comm_path_v1()
BEGIN
  IF EXISTS (SELECT 1 FROM content_vocabulary cv JOIN vocabulary_entry v ON v.id=cv.vocabulary_id JOIN content_item ci ON ci.id=cv.content_item_id JOIN lesson_section ls ON ls.id=ci.section_id JOIN lesson l ON l.id=ls.lesson_id JOIN unit u ON u.id=l.unit_id JOIN textbook t ON t.id=u.textbook_id WHERE t.source_code LIKE 'LP-OWNED-COMM-%' AND v.dictionary_status='HIDDEN') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Communication release blocked: a source vocabulary entry is hidden in the canonical dictionary.';
  END IF;
  IF EXISTS (SELECT 1 FROM content_item ci JOIN jlas_comm_expected e ON e.section_id=ci.section_id WHERE ci.order_index>e.items) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Communication release blocked: stale content items remain beyond the generated list; a shorter list needs a migration.';
  END IF;
  IF EXISTS (SELECT 1 FROM grammar_point gp JOIN jlas_comm_expected e ON e.lesson_id=gp.lesson_id WHERE gp.order_index>e.grammar) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Communication release blocked: stale grammar points remain beyond the generated list; a shorter list needs a migration.';
  END IF;
  IF EXISTS (SELECT 1 FROM dialogue_role r JOIN jlas_comm_expected e ON e.lesson_id=r.lesson_id WHERE r.code NOT REGEXP '^ROLE-[0-9]+$' OR CAST(SUBSTRING(r.code,6) AS UNSIGNED)>e.roles) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Communication release blocked: stale dialogue roles remain beyond the generated list; a shorter list needs a migration.';
  END IF;
END//
DELIMITER ;
DROP TEMPORARY TABLE IF EXISTS jlas_comm_expected;
CREATE TEMPORARY TABLE jlas_comm_expected (section_id BIGINT UNSIGNED NOT NULL PRIMARY KEY, lesson_id BIGINT UNSIGNED NOT NULL, items INT UNSIGNED NOT NULL, grammar INT UNSIGNED NOT NULL, roles INT UNSIGNED NOT NULL);
START TRANSACTION;
