INSERT INTO tag (code,name,tag_type) VALUES (CONVERT(X'4c502d4f574e45442d53504545442d4e332d434f4d50524548454e53494f4e' USING utf8mb4),CONVERT(X'4c6561726e696e672d6f776e6564205370656564204d6173746572204e332072656164696e672f6c697374656e696e67' USING utf8mb4),'KNOWLEDGE') ON DUPLICATE KEY UPDATE name=VALUES(name);
